-- Native multi-provider print-on-demand creative and fulfillment plane.
CREATE TABLE IF NOT EXISTS store_pod_providers (id TEXT PRIMARY KEY,name TEXT NOT NULL,priority INTEGER NOT NULL,free_entry INTEGER NOT NULL DEFAULT 1,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS store_pod_design_templates (id TEXT PRIMARY KEY,theme TEXT NOT NULL,title TEXT NOT NULL,text_primary TEXT NOT NULL,text_secondary TEXT NOT NULL DEFAULT '',scripture_ref TEXT NOT NULL DEFAULT '',art_motif TEXT NOT NULL DEFAULT 'type',active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE IF NOT EXISTS store_pod_designs (id TEXT PRIMARY KEY,template_id TEXT NOT NULL,day_key TEXT NOT NULL,theme TEXT NOT NULL,title TEXT NOT NULL,text_primary TEXT NOT NULL,text_secondary TEXT NOT NULL DEFAULT '',scripture_ref TEXT NOT NULL DEFAULT '',art_motif TEXT NOT NULL DEFAULT 'type',status TEXT NOT NULL DEFAULT 'ready',created_at INTEGER NOT NULL,UNIQUE(day_key,theme));
CREATE INDEX IF NOT EXISTS idx_store_pod_designs_day ON store_pod_designs(day_key,theme);
CREATE TABLE IF NOT EXISTS store_pod_product_types (id TEXT PRIMARY KEY,name TEXT NOT NULL,category_slug TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE IF NOT EXISTS store_pod_jobs (id TEXT PRIMARY KEY,design_id TEXT NOT NULL,product_type_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'design_ready',provider TEXT NOT NULL DEFAULT '',provider_product_id TEXT NOT NULL DEFAULT '',provider_variant_id TEXT NOT NULL DEFAULT '',external_order_id TEXT NOT NULL DEFAULT '',last_error TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(design_id,product_type_id));
